#define NULL 0

class stringx
{
public:
  stringx();
  stringx(const char*, int = -1);
  stringx(const stringx&);
  ~stringx();
  stringx& operator=(const stringx&);
  const char* c_str() const;
private:
  void* data;
  int reserved[3];
};

stringx operator+(const stringx&, const char*);

class script_object;

class script_manager
{
public:
  script_object* find_object(const stringx&) const;
};

class script_library_class
{
public:
  script_library_class(const char*, int, const char* = 0);
  virtual ~script_library_class();
  virtual unsigned find_instance(const stringx&) const;
  virtual void read_value(void*, char*);
  virtual void purge();
private:
  char layout[28];
};

void error(const char*, ...);

class slc_script_object_t : public script_library_class
{
protected:
  const script_manager& sman;
  script_object* sobj;
public:
  slc_script_object_t(const script_manager&, const char*);
};

slc_script_object_t::slc_script_object_t(const script_manager& sm,const char* n)
  : script_library_class(n,4,NULL),
    sman(sm)
{
  sobj = sman.find_object(n);
  if (!sobj)
  {
    stringx err;
    err=stringx("script object ")+n+" not found\n";
    error(err.c_str());
  }
}
